    char* next         = strstr(src, pattern);
    while (*src != '\0') {
        while (src != next && *src != '\0') {
            *dest = *src;
            ++dest;
            ++src;
        }
        if (*src == '\0') break;

        src += length_pattern;
        next = strstr(src, pattern);
    }
    *dest = '\0';
}

int check_duplicate(Records* self, const char* str)
{
    for (int i = 0; i < self->size; ++i) {
        if (strcmp(self->record[i][0], str) == 0) {
            return 0;
        }
    }
    return 1;
}

