LIST_HEAD(ready_queue);
LIST_HEAD(sleep_queue);

/* current running task PCB */
pcb_t * volatile current_running;

/* global process id */
pid_t process_id = 1;

/* 
 * Only modify PCB, current_running, process_id and ready_queue
 * DO NOT STORE OR RESTORE 
 * trick: modify $tp in ret_from_exception to ensure
 * disable_preempt() and enable_preempt() modify the same PCB
 */
void scheduler(void)
{
    pcb_t *prev_running = current_running;

    /* the task leaving the CPU is still runnable unless it blocked or
     * exited, so let it compete for the CPU again. pid0 is the kernel
     * idle task and never joins the ready queue. */
    if (prev_running != &pid0_pcb && prev_running->status == TASK_RUNNING) {
        prev_running->status = TASK_READY;
        prev_running->ready_tick = get_ticks();
        list_add_tail(&prev_running->list, &ready_queue);
    }

    /* pick the task with the highest dynamic priority, or idle */
    list_node_t *next_node = max_priority_node();
    if (next_node == NULL) {
        current_running = &pid0_pcb;
    } else {
        list_del(next_node);
        current_running = list_entry(next_node, pcb_t, list);
    }
    current_running->status = TASK_RUNNING;

    /* the screen cursor belongs to the task that owns the CPU */
    screen_cursor_x = current_running->cursor_x;
    screen_cursor_y = current_running->cursor_y;
}

