input.new_string:
/* look up a live task by process id */
static pcb_t *find_pcb(pid_t pid)
{
    for (int i = 0; i < NUM_MAX_TASK; i++) {
        if (pcb[i].pid == pid) {
            return &pcb[i];
        }
    }
    return NULL;
}

int do_kill(pid_t pid)
{
    /* pid 0 is the kernel and pid 1 is the shell, they have to stay alive */
    if (pid <= 1) {
        return 0;
    }

    disable_preempt();

    pcb_t *victim = find_pcb(pid);
    if (victim == NULL || victim->status == TASK_EXITED ||
        victim->status == TASK_ZOMBIE || victim->status == TASK_KILLED) {
        enable_preempt();
        return 0;
    }

    release_resources(victim);

    if (victim == current_running[cpu_id]) {
        /* killing ourselves is just an exit */
        retire_pcb(victim);
        scheduler();
    } else if (victim->status == TASK_RUNNING) {
        /* it owns the other core right now, and we must not pull the kernel
         * stack or the page table from under it: that core retires it on its
         * next schedule */
        victim->status = TASK_KILLED;
    } else {
        retire_pcb(victim);
    }

    enable_preempt();
    return 1;
}

int do_waitpid(pid_t pid, reg_t ignore1, reg_t ignore2, reg_t ingnore3, regs_context_t *regs)
{
    disable_preempt();

    pcb_t *child = find_pcb(pid);

    /* nothing to wait for: it never existed, it is already gone, or it is us */
    if (child == NULL || child->status == TASK_EXITED ||
        child == current_running[cpu_id]) {
        enable_preempt();
        return 0;
    }

    if (child->status == TASK_ZOMBIE) {
        /* collect the corpse: hand back its memory and its table slot */
        free_user_page(kva2pa(child->kernel_stack_base - PAGE_SIZE));
        child->status = TASK_EXITED;
        child->pid = -1;
        enable_preempt();
        return 1;
    }

    /*
     * The child is still alive, so wait on it. A blocked task always resumes
     * in user space right after the ecall that blocked it, so rewind sepc to
     * that ecall: once the child exits we are woken up and simply retry the
     * syscall. The retry needs the pid in a0 again, hence the return value.
     */
    regs->sepc -= 4;
    do_block(&current_running[cpu_id]->list, &child->wait_list);
    scheduler();

    enable_preempt();
    return pid;
}

