/* host main() for the kernel unit tests; compiled with the real libc headers */
#include <stdarg.h>
#include <stdio.h>

int host_printf(const char *fmt, ...)
{
    va_list va;
    int ret;
    va_start(va, fmt);
    ret = vprintf(fmt, va);
    va_end(va);
    return ret;
}

extern int run_tests(void);

int main(void)
{
    return run_tests();
}

