/*
 * Copy the arguments of a new process to the top of its own stack: they are
 * read from the address space of the caller, which is still the one we run in.
 * Returns the user address of the `argv` array.
 */
static uintptr_t init_user_args(pcb_t *new_pcb, int argc, char *argv[])
{
    uintptr_t pgdir = (uintptr_t)new_pcb->pgdir;
    uintptr_t arg_va[MAX_EXEC_ARGC];
    uintptr_t sp = USER_STACK_ADDR;
    int copied = 0;

    if (argc > MAX_EXEC_ARGC) {
        argc = MAX_EXEC_ARGC;
    }

    /* the strings themselves live at the very top of the stack */
    enable_sum();
    for (int i = argc - 1; i >= 0; i--) {
        int length = strlen(argv[i]) + 1;
        if (copied + length > MAX_EXEC_ARG_SIZE) {
            /* whatever is left does not fit into the first page of stack */
            argc = i + 1;
            break;
        }
        copied += length;
        sp -= length;
        memcpy((uint8_t *)get_kva_of(sp, pgdir), (uint8_t *)argv[i], length);
        arg_va[i] = sp;
    }
    disable_sum();

    /* then the argv array itself, NULL terminated as main() expects it */
    sp = ROUNDDOWN(sp, sizeof(uintptr_t)) - (argc + 1) * sizeof(uintptr_t);
    for (int i = 0; i < argc; i++) {
        *(uintptr_t *)get_kva_of(sp + i * sizeof(uintptr_t), pgdir) = arg_va[i];
    }
    *(uintptr_t *)get_kva_of(sp + argc * sizeof(uintptr_t), pgdir) = 0;

    /* the stack pointer of a RISC-V frame is 16 byte aligned */
    new_pcb->user_sp = ROUNDDOWN(sp, 16);
    return sp;
}

