/*
 * Host-side unit test for the Project 4 process management: exec of an ELF
 * image into a fresh address space, the scheduler's address space switch, and
 * the teardown of a process on exit, kill and waitpid.
 *
 * kernel/sched/sched.c and kernel/mm/mm.c are compiled for the host against
 * the shims in hostshim/; the "ELF image" and the "SD card" are host buffers.
 */
#include <os/sched.h>
#include <os/mm.h>
#include <os/irq.h>
#include <os/binsem.h>
#include <os/elf.h>
#include <pgtable.h>
#include <user_programs.h>

/* --- the simulated machine --- */
unsigned char *host_phys_mem;
unsigned long host_satp;

static uint64_t fake_ticks;
uint64_t host_ticks(void) { return fake_ticks; }

uintptr_t sbi_sd_write(unsigned int a, unsigned int n, unsigned int b)
{
    (void)a; (void)n; (void)b;
    return 0;
}
uintptr_t sbi_sd_read(unsigned int a, unsigned int n, unsigned int b)
{
    (void)a; (void)n; (void)b;
    return 0;
}

/* --- stubs for the rest of the kernel --- */
int cpu_id;
int screen_cursor_x[NR_CPUS];
int screen_cursor_y[NR_CPUS];

int printk(const char *fmt, ...) { (void)fmt; return 0; }
void __global_pointer$(void) {}
void enable_sum(void) {}
void disable_sum(void) {}
void handle_other(regs_context_t *r, uint64_t s, uint64_t c) { (void)r; (void)s; (void)c; }

int preempt_depth;
