        kernel_pcb[i].pid = 0;
        kernel_pcb[i].type = KERNEL_PROCESS;
        kernel_pcb[i].status = TASK_RUNNING;
        kernel_pcb[i].priority = 0;
        kernel_pcb[i].mask = 1lu << i;
        kernel_pcb[i].cpu_id = i;
        kernel_pcb[i].preempt_count = 0;
        kernel_pcb[i].binsem_num = 0;
        kernel_pcb[i].pgdir = (PTE *)PGDIR_PA;
        kernel_pcb[i].kernel_sp = pa2kva(KERNEL_MEM_BEGIN + (i + 1) * PAGE_SIZE);
        kernel_pcb[i].user_sp = kernel_pcb[i].kernel_sp;
        kernel_pcb[i].cursor_x = 1;
        kernel_pcb[i].cursor_y = 1;
