    CHECK(*(unsigned char *)get_kva_of(0x11000, pgdir) == 0);
    CHECK(*(unsigned char *)get_kva_of(0x12000, pgdir) == 0);

    /* argc and argv are handed to main() in a0/a1 */
    CHECK(regs->regs[10] == 2);
    uintptr_t argv_base = regs->regs[11];
    CHECK(argv_base < USER_STACK_ADDR && argv_base > USER_STACK_ADDR - PAGE_SIZE);
    uintptr_t *argv_user = (uintptr_t *)get_kva_of(argv_base, pgdir);
    CHECK(argv_user[2] == 0);                   /* NULL terminated */
    CHECK(strcmp((char *)get_kva_of(argv_user[0], pgdir), "prog") == 0);
    CHECK(strcmp((char *)get_kva_of(argv_user[1], pgdir), "0x30000000") == 0);
    /* the stack pointer starts below the arguments, aligned for a frame */
    CHECK(regs->regs[2] == task->user_sp);
    CHECK(task->user_sp <= argv_base);
    CHECK((task->user_sp & 15) == 0);

    /* the scheduler moves this core into the address space of the task */
    unsigned long kernel_satp = host_satp;
    scheduler();
    CHECK(current_running[0] == task);
    CHECK(current_cpu_running == task);
    CHECK(task->status == TASK_RUNNING);
    CHECK(host_satp != kernel_satp);
    CHECK((host_satp & ((1lu << 44) - 1)) == (uintptr_t)task->pgdir >> NORMAL_PAGE_SHIFT);
    CHECK(host_satp >> 60 == SATP_MODE_SV39);
    CHECK(screen_cursor_x[0] == 1 && screen_cursor_y[0] == 1);

    /* and everything the process owns is handed back when it exits */
    do_exit();
    CHECK(task->status == TASK_EXITED);
    CHECK(task->pgdir == (PTE *)PGDIR_PA);
    CHECK(host_satp >> 60 == SATP_MODE_SV39);
    CHECK((host_satp & ((1lu << 44) - 1)) == PGDIR_PA >> NORMAL_PAGE_SHIFT);
    CHECK(queue_contains(&kernel_pcb[0].wait_list, &task->list));
    CHECK(current_running[0] == &kernel_pcb[0]);
    /* the kernel stack is freed by the idle task, the rest is gone already */
    CHECK(free_page_num() == free_before - 1);
    for (int i = 0; i < PGDIR_PAGE_NUM; i++) CHECK(pgdir_page[i].valid == 0);
}

static void test_exec_limits(void)
{
    reset_kernel();
    char arg0[] = "prog";
    char *argv[] = {arg0};

    /* the process table is not endless */
    for (int i = 0; i < NUM_MAX_TASK; i++) {
        CHECK(do_exec("prog", 1, argv, AUTO_CLEANUP_ON_EXIT) > 0);
    }
    CHECK(do_exec("prog", 1, argv, AUTO_CLEANUP_ON_EXIT) == 0);

    /* neither is the memory: the shell tells the two apart */
    reset_kernel();
    for (int i = 0; i < USER_PAGE_NUM; i++) user_page[i].valid = 1;
    CHECK(do_exec("prog", 1, argv, AUTO_CLEANUP_ON_EXIT) == -2);
    CHECK(pcb[0].pid == -1);
}

static void test_kill_and_waitpid(void)
{
    reset_kernel();
    unsigned long free_before = free_page_num();

    char arg0[] = "prog";
    char *argv[] = {arg0};
    pid_t victim = do_exec("prog", 1, argv, AUTO_CLEANUP_ON_EXIT);
    pcb_t *victim_pcb = &pcb[0];

    /* somebody waiting for it has to be woken up when it dies */
    pcb_t *waiter = &pcb[1];
    waiter->pid = 42;
    waiter->status = TASK_BLOCKED;
    waiter->mask = 3;
    waiter->priority = 0;
    waiter->ready_tick = 0;
    list_add_tail(&waiter->list, &victim_pcb->wait_list);

    /* it also holds a binary semaphore somebody else is blocked on */
    int sem = 7;
    binsem_nodes[sem].sem = 0;
    victim_pcb->binsem_id[0] = sem;
    victim_pcb->binsem_num = 1;
    pcb_t *blocked = &pcb[2];
    blocked->pid = 43;
    blocked->status = TASK_BLOCKED;
    blocked->mask = 3;
    blocked->priority = 0;
    blocked->ready_tick = 0;
    blocked->binsem_num = 0;
    list_add_tail(&blocked->list, &binsem_nodes[sem].block_queue);

    CHECK(do_kill(1) == 0);                    /* the shell may not be killed */
    CHECK(do_kill(999) == 0);                  /* neither may a ghost */
    CHECK(do_kill(victim) == 1);
    CHECK(victim_pcb->status == TASK_EXITED);
    CHECK(victim_pcb->pgdir == (PTE *)PGDIR_PA);
    CHECK(free_page_num() == free_before - 1); /* only its kernel stack is left */
    CHECK(waiter->status == TASK_READY);
    CHECK(queue_contains(&ready_queue, &waiter->list));
    CHECK(blocked->status == TASK_READY);
    CHECK(blocked->binsem_num == 1 && blocked->binsem_id[0] == sem);
    CHECK(do_kill(victim) == 0);               /* it only dies once */

    /* a zombie keeps its slot until somebody collects it */
    reset_kernel();
    free_before = free_page_num();
    pid_t child = do_exec("prog", 1, argv, ENTER_ZOMBIE_ON_EXIT);
    pcb_t *child_pcb = &pcb[0];
    regs_context_t regs;
    regs.sepc = 0x10040;

    /* waiting for a live child blocks the caller and rewinds the ecall */
    current_running[0] = &kernel_pcb[0];
    CHECK(do_waitpid(child, 0, 0, 0, &regs) == child);
    CHECK(regs.sepc == 0x1003c);
    CHECK(queue_contains(&child_pcb->wait_list, &kernel_pcb[0].list));
    CHECK(kernel_pcb[0].status == TASK_BLOCKED);

    /* the child exits: the waiter runs again, the corpse is still there */
    current_running[0] = child_pcb;
    child_pcb->status = TASK_RUNNING;
    do_exit();
    CHECK(child_pcb->status == TASK_ZOMBIE);
    CHECK(child_pcb->pid == child);
    CHECK(kernel_pcb[0].status == TASK_READY || kernel_pcb[0].status == TASK_RUNNING);
    CHECK(free_page_num() == free_before - 1);

    /* and now waitpid collects it */
    current_running[0] = &kernel_pcb[0];
    CHECK(do_waitpid(child, 0, 0, 0, &regs) == 1);
    CHECK(child_pcb->pid == -1);
    CHECK(child_pcb->status == TASK_EXITED);
    CHECK(free_page_num() == free_before);
    CHECK(do_waitpid(child, 0, 0, 0, &regs) == 0);
}

static void test_scheduler_affinity(void)
{
    reset_kernel();
    char arg0[] = "prog";
    char *argv[] = {arg0};

    kernel_pcb[0].mask = 2;                    /* the child may only run on core 1 */
    do_exec("prog", 1, argv, AUTO_CLEANUP_ON_EXIT);
    pcb_t *task = &pcb[0];
    CHECK(task->mask == 2);

    cpu_id = 0;
    scheduler();
    CHECK(current_running[0] == &kernel_pcb[0]); /* core 0 stays idle */
    CHECK(task->status == TASK_READY);

    cpu_id = 1;
    current_running[1] = &kernel_pcb[1];
    scheduler();
    CHECK(current_running[1] == task);
    CHECK(task->cpu_id == 1);

    /* killing a task which owns the other core is left to that core */
    cpu_id = 0;
    CHECK(do_kill(task->pid) == 1);
    CHECK(task->status == TASK_KILLED);
    CHECK(task->pgdir != (PTE *)PGDIR_PA);

    cpu_id = 1;
    scheduler();
    CHECK(task->status == TASK_EXITED);
    CHECK(task->pgdir == (PTE *)PGDIR_PA);
    CHECK(current_running[1] == &kernel_pcb[1]);
}

int run_tests(void)
{
    host_phys_mem = (unsigned char *)host_calloc(HOST_PHYS_SIZE, 1);
    if (host_phys_mem == NULL) {
        host_printf("p4 sched: cannot allocate the simulated physical memory\n");
        return 1;
    }
    build_prog_image();

    test_exec();
    test_exec_limits();
    test_kill_and_waitpid();
    test_scheduler_affinity();

    if (failures == 0) {
        host_printf("p4 sched: all exec/exit/kill/waitpid checks passed\n");
    }
    return failures != 0;
}

